<script setup lang="ts">
import {computed,ref,toRef,watch} from 'vue'
import DateInput from '../../../components/common/DateInput.vue'
import {useStaffWallet} from '../../wallet/useStaffWallet'
import {useCardText} from '../text'
import {cardApi} from '../api'
import {dateTime,money} from '../format'
import type {Plan} from '../types'
import type {ReportRow} from './types'
import {useCardBusinessReport} from './useCardBusinessReport'
import CardReportRows from './CardReportRows.vue'
import CardReportSummary from './CardReportSummary.vue'
import './report.css'
const props=defineProps<{store:string;plans:Plan[];canReverse:boolean;disabled:boolean}>(),emit=defineEmits<{changed:[];error:[message:string]}>(),{t,locale}=useCardText(),{context}=useStaffWallet(),x=(zh:string,en:string)=>locale.value.startsWith('en')?en:zh
const {mode,page,size,data,loading,error,draft,applied,dirty,resetKey,fromValid,toValid,load,search,reset,move,epoch}=useCardBusinessReport(toRef(props,'store'),()=>context.value?.store?.timezone||'Asia/Singapore')
const selected=ref<ReportRow|null>(null),reason=ref(''),reversing=ref(false),confirming=ref(false)
const totalPages=computed(()=>Math.max(1,Math.ceil((data.value?.total??0)/size.value)))
watch([()=>props.store,applied],()=>{selected.value=null;reason.value='';confirming.value=false})
async function reverse(){const row=selected.value;if(!row||!row.reversible||!props.canReverse||props.disabled||reversing.value||!reason.value.trim())return;const store=props.store,g=epoch();reversing.value=true;try{await cardApi(store).command(`/entries/${row.id}/${row.kind==='stamp'?'reverse-stamp':'reverse'}`,{reason:reason.value.trim()},row.kind==='stamp'?'stamp.reverse':'redeem.reverse');if(g===epoch()){selected.value=null;reason.value='';confirming.value=false;emit('changed');await load()}}catch(e){if(g===epoch()){error.value=e instanceof Error?e.message:String(e);emit('error',error.value)}}finally{reversing.value=false}}
</script>
<template><section class="cards-panel card-business-report"><h2>{{x('卡业务报表','Card business reports')}}</h2><nav class="card-report-modes" :aria-label="x('报表类型','Report type')"><button v-for="v in (['details','summary','expiry'] as const)" :key="v" type="button" :class="{primary:mode===v}" :aria-pressed="mode===v" :disabled="reversing" @click="mode=v">{{v==='details'?x('业务明细','Activity'):v==='summary'?x('汇总统计','Summary'):x('额度到期','Allowance expiry')}}</button></nav>
<form class="card-report-filters" @submit.prevent="selected=null;search()"><label>{{mode==='expiry'?x('到期起日','Expiry from'):x('办理起日','Handled from')}}<DateInput v-model="draft.from" :reset-key="resetKey" required @validity-change="fromValid=$event"/></label><label>{{mode==='expiry'?x('到期止日','Expiry to'):x('办理止日','Handled to')}}<DateInput v-model="draft.to" :reset-key="resetKey" required @validity-change="toValid=$event"/></label><label>{{t('customer')}}<input v-model="draft.query" maxlength="120" :placeholder="x('姓名或手机号','Name or phone')"></label><label>{{t('plans')}}<select v-model="draft.planId"><option value="">{{x('全部卡方案','All plans')}}</option><option v-for="plan in plans" :key="plan.id" :value="plan.id">{{locale.startsWith('en')?(plan.nameEn||plan.nameZh):plan.nameZh}}</option></select></label><label v-if="mode!=='expiry'">{{x('业务类型','Activity type')}}<select v-model="draft.kind"><option value="all">{{x('全部业务','All activity')}}</option><option value="redeem">{{t('redeem')}}</option><option value="stamp">{{t('stampAction')}}</option><option value="grant">{{x('领卡 / 发放奖励','Card / reward grants')}}</option><option value="refund">{{x('退卡','Card refunds')}}</option><option value="reversal">{{x('冲正 / 撤回','Reversals')}}</option></select></label><label v-if="mode!=='details'">{{x('汇总维度','Group by')}}<select v-model="draft.groupBy"><option value="plan">{{x('卡方案','Card plan')}}</option><option value="customer">{{t('customer')}}</option></select></label><div class="cards-actions"><button class="primary" :disabled="loading||reversing">{{x('查询','Search')}}</button><button type="button" :disabled="loading||reversing" @click="selected=null;reset()">{{x('重置','Reset')}}</button></div></form>
<p class="cards-caption">{{mode==='expiry'?x('按到期归属日查询；含不限总次数周期卡的按日额度计算，不计入实际消费。','By expiry business date. Includes calculated unlimited-period allowances; excluded from consumption.'):x('按门店时区的实际办理时间查询，业务归属日期单独列示。汇总覆盖全部筛选结果。','Filters use actual handling time in the store timezone; business date is separate. Totals cover all matching entries.')}}</p><p v-if="dirty" role="status" class="cards-caption">{{x('筛选已修改，请查询更新结果。','Filters changed. Search to update results.')}}</p><p v-if="loading" role="status">{{t('loading')}}</p><p v-if="error" role="alert" class="cards-error">{{error}} <button type="button" :disabled="loading" @click="load">{{t('refresh')}}</button></p>
<template v-if="data"><div class="card-report-count"><strong>{{data.total}}</strong> {{x('笔记录','entries')}} <span>{{x('门店时区','Store timezone')}} {{data.timezone}}</span></div><dl v-if="mode==='summary'&&data.money" class="cards-report-totals"><div><dt>{{t('received')}}</dt><dd>{{money(data.money.receivedCents)}}</dd></div><div><dt>{{t('refundAmount')}}</dt><dd>{{money(data.money.refundedCents)}}</dd></div></dl><p v-if="!data.total" class="cards-empty">{{x('暂无符合条件的卡业务记录','No matching card entries')}}</p><p v-if="mode==='summary'" class="cards-caption">{{x('净发生量仅对当前筛选结果计算，可为负数；核对完整期间请选全部业务。净值不是当前剩余权益。','Net activity uses only the current filters and may be negative. Select all activity for the full period; net activity is not the current balance.')}}</p><CardReportSummary v-if="mode==='summary'||mode==='expiry'" :rows="data.summary" :expiry="mode==='expiry'" :by-customer="applied.groupBy==='customer'"/><CardReportRows v-if="mode!=='summary'&&data.items.length" :rows="data.items" :timezone="data.timezone" :disabled="reversing" @select="selected=$event;confirming=false;reason=''"/><nav v-if="mode!=='summary'" class="card-report-pagination" :aria-label="x('报表分页','Report pagination')"><button :disabled="loading||dirty||page===0" @click="move(-1)">{{x('上一页','Previous')}}</button><span>{{page+1}} / {{totalPages}} · {{x('每页','Page size')}} {{size}}</span><button :disabled="loading||dirty||(page+1)*size>=data.total" @click="move(1)">{{x('下一页','Next')}}</button></nav></template>
<section v-if="selected&&data" class="cards-notice card-report-detail" :aria-label="t('details')"><header class="cards-section-heading"><h3>{{t('details')}}</h3><button type="button" :disabled="reversing" @click="selected=null;confirming=false">{{t('close')}}</button></header><p>{{x('办理时间','Handled')}} {{selected.createdAt?dateTime(selected.createdAt,data.timezone):x('按日计算，无独立办理时间','Calculated daily; no handling timestamp')}} · {{x('业务日期','Business date')}} {{selected.businessDay}}</p><p>{{t('reason')}}：{{selected.reason||'—'}}</p><details><summary>{{x('审计信息','Audit information')}}</summary><p>{{t('recordSource')}}：{{selected.source}}</p><p v-if="selected.ledgerQuantity!==undefined&&selected.ledgerQuantity!==selected.quantity">{{x('账本原始数量','Original ledger quantity')}}：{{selected.ledgerQuantity}}</p><p>{{x('记录编号','Entry ID')}}：{{selected.id}}</p><p v-if="selected.originalId">{{t('linked')}}：{{selected.originalId}}</p></details><button v-if="canReverse&&selected.reversible" :disabled="disabled||reversing" @click="confirming=!confirming">{{selected.kind==='stamp'?x('撤回集次','Reverse stamp'):t('reverse')}}</button><form v-if="confirming" @submit.prevent="reverse"><label>{{t('reason')}}<input v-model="reason" required maxlength="500" :disabled="reversing"></label><button :disabled="disabled||reversing||!reason.trim()">{{t('confirm')}}</button></form></section>
</section></template>
